import React from "react";
import { WeightInfoProps } from "../molecules/weightInfo";
import WeightInfo from "../molecules/weightInfo";
import { Card } from "@mui/material";



const WeightCard = ({length, width, grammage, numberOfSheets, setNumberOfSheets} : WeightInfoProps) => {


    return(

        <>

            <Card>

                <WeightInfo length={length} width={width} grammage={grammage} numberOfSheets={numberOfSheets} setNumberOfSheets={setNumberOfSheets}/>

            </Card>

        </>


    )

}


export default WeightCard;
